def market(code: str) -> dict:
    try:
        return dict(MARKETS[code.upper()])
    except KeyError as exc:
        raise ValueError("unknown market") from exc


def session_minutes(code: str, friday: bool = False) -> int:
    """Nominal session-window minutes; auctions and special dates need separate handling."""
    m = market(code)
    sessions = m.get("friday", m["session"]) if friday else m["session"]
    return sum((int(b[:2])*60+int(b[3:]))-(int(a[:2])*60+int(a[3:]))
               for a, b in sessions)


def settlement_date(code: str, trade_date, holidays: Iterable = (), *, lag: int | None = None):
    """Weekday arithmetic, with dated transition only where sourced.

    Pass exchange, custodian and currency holidays. Vietnam historical regimes require
    explicit lag; the 2022 intraday delivery-time change is not used as a T+3/T+2 switch.
    """
    d = date.fromisoformat(str(trade_date))
    m = market(code)
    if lag is None:
        if m["t2_from"] is None:
            raise ValueError("explicit settlement lag required for this market")
        if d < date(2010, 1, 1):
            raise ValueError("historical settlement regime not covered")
        lag = 2 if d >= m["t2_from"] else 3
    if not isinstance(lag, int) or lag < 0:
        raise ValueError("lag must be a nonnegative integer")
    closed = {date.fromisoformat(str(h)) for h in holidays}
    current = d
    while lag:
        current += timedelta(days=1)
        if current.weekday() < 5 and current not in closed:
            lag -= 1
    return current


def foreign_premium(room: float, cap: float = 0.20, scale: float = 0.03) -> float:
    """The -F line's premium over the local line as a function of remaining foreign room.

    `room` is the unused ownership fraction in the scenario (foreign_limit - foreign_held).
    At room = 0 the chosen premium is the full `cap`; it decays as room opens. Actual
    registration/transfer rules and available offers must be checked separately.

    The exponential shape and positive premium are SCENARIO ASSUMPTIONS. Real foreign
    lines can have discounts, stale quotes or no liquidity. No universal premium follows
    from a foreign ownership limit.
    """
    if not all(math.isfinite(v) for v in (room, cap, scale)) or cap < 0 or scale <= 0:
        raise ValueError("cap must be non-negative and scale positive")
    r = max(float(room), 0.0)
    return float(cap * math.exp(-r / scale))


def foreign_price(local_price: float, room: float, cap: float = 0.20,
                  scale: float = 0.03) -> float:
    """Hypothetical foreign-line price under the chosen premium scenario."""
    if not math.isfinite(local_price) or local_price <= 0:
        raise ValueError("local_price must be positive")
    return local_price * (1.0 + foreign_premium(room, cap, scale))


def can_a_foreigner_buy(room: float, has_foreign_board: bool,
                         foreign_transfer_available: bool = False) -> tuple[bool | None, str]:
    """Room is a gate on new aggregate foreign ownership, not every possible transfer.

    Existing foreign-to-foreign holdings, negotiated transfers and NVDR eligibility need
    their own checks. Presence of a foreign board does not prove offers exist there.
    """
    if not math.isfinite(room):
        raise ValueError("room must be finite")
    if foreign_transfer_available:
        return True, "supplied eligible foreign-to-foreign transfer capacity"
    if room > 0:
        return True, "ownership-room gate passed; order size and liquidity still required"
    if has_foreign_board:
        return None, "no new room; verify foreign-line offer or NVDR eligibility separately"
    return False, "new-room purchase blocked; eligible existing-foreign transfer is separate"


def synthetic_room_and_price(n_days: int = 1_250, seed: int = 20260910,
                             foreign_limit: float = 0.49,
                             start_held: float = 0.44, daily_vol: float = 0.017,
                             flow_vol: float = 0.004, flow_drift: float = 0.00012,
                             cap: float = 0.20, scale: float = 0.03) -> pd.DataFrame:
    """A seeded local price plus a foreign-ownership path that presses against the limit.

    Foreign holdings drift up (a name foreigners want) with noise, and are hard-capped at
    the ownership limit. `room` is what is left. The -F price is the local price times the
    premium implied by that room. Returns local, room, premium, foreign price and a flag
    for whether a foreigner could have bought on the local board that day.
    """
    if (n_days < 2 or not 0 < foreign_limit <= 1 or not 0 <= start_held <= foreign_limit
            or daily_vol < 0 or flow_vol < 0):
        raise ValueError("invalid series length, holding or volatility assumptions")
    rng = np.random.default_rng(seed)
    ret = rng.normal(0.0004, daily_vol, n_days)
    local = 100.0 * np.exp(np.cumsum(ret))
    held = np.empty(n_days)
    h = start_held
    for i in range(n_days):
        h = min(foreign_limit, max(0.0, h + flow_drift + rng.normal(0.0, flow_vol)))
        held[i] = h
    room = foreign_limit - held
    prem = np.array([foreign_premium(r, cap, scale) for r in room])
    idx = pd.bdate_range("2021-01-04", periods=n_days)
    return pd.DataFrame({"local": local, "foreign_held": held, "room": room,
                         "premium": prem, "foreign": local * (1.0 + prem),
                         "local_board_open_to_foreigners": room > 1e-9}, index=idx)


def foreign_vs_local_return(df: pd.DataFrame, hold_days: int = 60) -> dict[str, float]:
    """Buy and hold `hold_days`, priced on the local line and on the -F line.

    Every valid entry date is used; windows overlap. The return gap comes from the premium
    ratio between endpoints and interacts with the local gross return. A constant premium
    cancels, even when its price level is substantial.
    """
    if hold_days < 1:
        raise ValueError("hold_days must be at least 1")
    loc = df["local"].to_numpy()
    frn = df["foreign"].to_numpy()
    prem = df["premium"].to_numpy()
    n = len(df) - hold_days
    if n <= 0:
        raise ValueError("series is shorter than the holding period")
    r_loc = loc[hold_days:] / loc[:n] - 1.0
    r_frn = frn[hold_days:] / frn[:n] - 1.0
    diff = r_frn - r_loc
    return {
        "n_windows": float(n),
        "hold_days": float(hold_days),
        "mean_local_pct": float(r_loc.mean() * 100),
        "mean_foreign_pct": float(r_frn.mean() * 100),
        "mean_gap_bps": float(diff.mean() * 1e4),
        "worst_gap_bps": float(diff.min() * 1e4),
        "best_gap_bps": float(diff.max() * 1e4),
        "windows_foreign_worse": float(int((diff < 0).sum())),
        "share_foreign_worse": float((diff < 0).mean()),
        "mean_premium_pct": float(prem.mean() * 100),
        "max_premium_pct": float(prem.max() * 100),
        "full_room_share": float((df["room"].to_numpy() <= 1e-9).mean()),
    }


def entry_cost_only(df: pd.DataFrame) -> dict[str, float]:
    """Price premium at each possible entry, ignoring subsequent changes.

    These are price-level statistics, NOT an extra return deduction. If the premium is
    unchanged at entry and exit, local and foreign percentage returns are identical.
    """
    prem = df["premium"].to_numpy()
    return {
        "mean_entry_premium_bps": float(prem.mean() * 1e4),
        "median_entry_premium_bps": float(np.median(prem) * 1e4),
        "p90_entry_premium_bps": float(np.percentile(prem, 90) * 1e4),
    }


def vietnam_blocked_days(df: pd.DataFrame) -> dict[str, float]:
    """Count blocked new-room purchases in the scenario; not all foreign transfers."""
    open_ = df["local_board_open_to_foreigners"].to_numpy()
    blocked = ~open_
    runs, cur = [], 0
    for b in blocked:
        if b:
            cur += 1
        elif cur:
            runs.append(cur)
            cur = 0
    if cur:
        runs.append(cur)
    return {
        "n_days": float(len(df)),
        "blocked_days": float(int(blocked.sum())),
        "blocked_share": float(blocked.mean()),
        "n_blocked_runs": float(len(runs)),
        "longest_run": float(max(runs)) if runs else 0.0,
    }


def main():
    print("Session snapshots are routing aids, not exchange calendars.")
    for code in MARKETS:
        print(code, "nominal window minutes=", session_minutes(code))
    frame = synthetic_room_and_price()
    stats = foreign_vs_local_return(frame)
    blocked = vietnam_blocked_days(frame)
    print("SYNTHETIC positive-premium scenario; no empirical premium estimate.")
    print(f"Windows={stats['n_windows']:.0f}; mean return gap={stats['mean_gap_bps']:.1f} bp; "
          f"worst={stats['worst_gap_bps']:.1f} bp; best={stats['best_gap_bps']:.1f} bp")
    print(f"Full-room new-purchase blocks={blocked['blocked_days']:.0f}/"
          f"{blocked['n_days']:.0f} ({blocked['blocked_share']:.1%})")
    fixed = pd.DataFrame({'local': [100., 110.], 'foreign': [120., 132.],
                          'premium': [.2, .2], 'room': [0., 0.]})
    print(f"Constant 20% premium: return gap="
          f"{foreign_vs_local_return(fixed, 1)['mean_gap_bps']:.1f} bp")
    print("RULE: verify ownership room, share line and executable offers; "
          "do not deduct a persistent foreign premium twice.")


if __name__ == "__main__":
    main()
